// Content OS · YouTube sync
// Pulls every public video from the last 90 days for each channel below and
// writes it into CONTENT STATS in Notion (updates the row if it already exists).
// Needs two Railway env vars: YT_API_KEY and NOTION_TOKEN.
// No client logins needed: this only reads public YouTube data.

// ---- Fill in each creator's YouTube handle (with the @). Leave '' to skip. ----
const CHANNELS = [
  { client: 'Brad',    handle: '' },
  { client: 'Chris',   handle: '' },
  { client: 'Lindsay', handle: '' },
  { client: 'Duncan',  handle: '' },
  { client: 'Valeri',  handle: '' },
  { client: 'Emtech',  handle: '' },
  { client: 'David',   handle: '' },
  { client: 'Nicole',  handle: '' }
];

const DS = 'e8265c69-3e3e-451b-8fe0-9b4bfcbe8960'; // CONTENT STATS data source
const DAYS_BACK = 90;

const YT = $env.YT_API_KEY;
const NOTION = $env.NOTION_TOKEN;
if (!YT) throw new Error('YT_API_KEY is empty. Add it in Railway and check N8N_BLOCK_ENV_ACCESS_IN_NODE=false');
if (!NOTION) throw new Error('NOTION_TOKEN is empty in Railway');

const http = opts => this.helpers.httpRequest(opts);
const yt = (path, qs) => http({ method: 'GET', url: `https://www.googleapis.com/youtube/v3/${path}`, qs: { ...qs, key: YT }, json: true });
const NH = { Authorization: `Bearer ${NOTION}`, 'Notion-Version': '2025-09-03', 'Content-Type': 'application/json' };
const notion = (method, path, body) => http({ method, url: `https://api.notion.com/v1/${path}`, headers: NH, body, json: true });
const sleep = ms => new Promise(r => setTimeout(r, ms));
const rt = s => [{ type: 'text', text: { content: String(s).slice(0, 1990) } }];
const istDate = ms => new Date(ms + 5.5 * 3600e3).toISOString().slice(0, 10);

const today = istDate(Date.now());
const cutoff = Date.now() - DAYS_BACK * 864e5;
const report = [];

for (const ch of CHANNELS) {
  if (!ch.handle) continue;
  const r = { client: ch.client, handle: ch.handle, created: 0, updated: 0, error: null };
  try {
    // 1. Channel -> uploads playlist
    const c = await yt('channels', { part: 'contentDetails', forHandle: ch.handle });
    const uploads = c.items && c.items[0] && c.items[0].contentDetails.relatedPlaylists.uploads;
    if (!uploads) throw new Error(`No channel found for ${ch.handle}`);

    // 2. Video IDs from the last DAYS_BACK days (uploads list is newest first)
    const ids = [];
    let pageToken = null, done = false;
    do {
      const pl = await yt('playlistItems', { part: 'contentDetails', playlistId: uploads, maxResults: 50, ...(pageToken ? { pageToken } : {}) });
      for (const it of pl.items || []) {
        const pub = it.contentDetails.videoPublishedAt;
        if (!pub) continue; // private or scheduled
        if (Date.parse(pub) < cutoff) { done = true; break; }
        ids.push(it.contentDetails.videoId);
      }
      pageToken = done ? null : pl.nextPageToken;
    } while (pageToken);

    // 3. Stats in batches of 50
    for (let i = 0; i < ids.length; i += 50) {
      const vr = await yt('videos', { part: 'snippet,statistics', id: ids.slice(i, i + 50).join(',') });
      for (const v of vr.items || []) {
        if (v.snippet.liveBroadcastContent === 'upcoming') continue;
        const s = v.statistics || {};
        const views = Number(s.viewCount || 0);
        const likes = s.likeCount != null ? Number(s.likeCount) : null;
        const comments = s.commentCount != null ? Number(s.commentCount) : null;
        const posted = istDate(Date.parse(v.snippet.publishedAt));
        const age = Math.round((Date.parse(today) - Date.parse(posted)) / 864e5);
        const key = `yt:${v.id}`;

        // Top comments (fails quietly if comments are off)
        let top = [];
        if (comments) {
          try {
            const ct = await yt('commentThreads', { part: 'snippet', videoId: v.id, maxResults: 3, order: 'relevance', textFormat: 'plainText' });
            top = (ct.items || []).map(x => {
              const cs = x.snippet.topLevelComment.snippet;
              return { u: cs.authorDisplayName, t: String(cs.textDisplay || '').slice(0, 200) };
            });
          } catch (e) { /* comments disabled */ }
        }

        // Existing row?
        const q = await notion('POST', `data_sources/${DS}/query`, { filter: { property: 'Video Key', rich_text: { equals: key } }, page_size: 1 });
        const page = q.results && q.results[0];
        let hist = [];
        if (page) {
          try {
            const raw = (page.properties['Views History'].rich_text || []).map(t => t.plain_text).join('');
            hist = raw ? JSON.parse(raw) : [];
          } catch (e) { hist = []; }
        }
        // Daily snapshot for the first 7 days after posting
        if (age <= 7) {
          hist = hist.filter(h => h.d !== today);
          hist.push({ d: today, v: views });
          hist.sort((a, b) => (a.d < b.d ? -1 : 1));
        }

        const props = {
          'Video': { title: rt(v.snippet.title || 'Untitled video') },
          'Client': { select: { name: ch.client } },
          'Platform': { select: { name: 'YouTube' } },
          'Video Key': { rich_text: rt(key) },
          'URL': { url: `https://www.youtube.com/watch?v=${v.id}` },
          'Posted': { date: { start: posted } },
          'Views': { number: views },
          'Likes': { number: likes },
          'Comments': { number: comments },
          'Views History': { rich_text: rt(JSON.stringify(hist.slice(0, 8))) },
          'Top Comments': { rich_text: rt(JSON.stringify(top)) },
          'Last Synced': { date: { start: new Date().toISOString() } }
        };

        if (page) { await notion('PATCH', `pages/${page.id}`, { properties: props }); r.updated++; }
        else { await notion('POST', 'pages', { parent: { type: 'data_source_id', data_source_id: DS }, properties: props }); r.created++; }
        await sleep(350); // stay under Notion's rate limit
      }
    }
  } catch (e) {
    r.error = (e && e.message) || String(e);
  }
  report.push({ json: r });
}

if (!report.length) return [{ json: { note: 'No handles filled in yet. Add them to CHANNELS at the top of this node.' } }];
return report;
